/* ---- Nov 22, 2026: heatmap, fair value, target history, segments, seasonality, superinvestors, congress, ETFs, saved screens, plans ---- */
.nx-src{font-size:12.5px;color:var(--mut);margin:10px 0 0;line-height:1.5}
.hm-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px}.hm-leg{display:flex;margin-left:auto;border-radius:8px;overflow:hidden}.hm-leg span{font:700 11px Inter,sans-serif;color:#fff;padding:5px 8px}
.hm-sum{display:flex;gap:18px;flex-wrap:wrap;font-size:13.5px;margin:0 0 10px;color:var(--mut)}.hm-sum b{color:inherit}.hm-sum b.up{color:#00995A}.hm-sum b.dn{color:#D72B45}
.hm-svg{background:#0F172A;border-radius:12px;overflow:hidden}.hm-svg svg{display:block;width:100%;height:auto}.hm-c{cursor:pointer}.hm-c:hover{stroke:#fff;stroke-width:2}
.subnav a.hm-tab{font-weight:700}
.fv-top{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.fv-big{border:2px solid var(--line);border-radius:14px;padding:12px 16px}.fv-big span{display:block;font-size:13px;color:var(--mut);font-weight:600}.fv-big b{display:block;font:800 28px 'Space Grotesk',sans-serif;margin:2px 0}.fv-big small{font-size:12.5px;color:var(--mut)}
.fv-bar{position:relative;height:12px;border-radius:8px;background:#EEF2F8;margin:40px 8px 18px}.fv-rng{position:absolute;top:0;bottom:0;background:#BDE8D1;border-radius:8px}
.fv-mk{position:absolute;top:-6px;width:4px;height:24px;border-radius:3px;transform:translateX(-50%)}.fv-mk em{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);white-space:nowrap;font:700 12px Inter,sans-serif;font-style:normal}
.fv-px{background:#0B1B3F}.fv-px em{color:#0B1B3F}.fv-fv{background:#00995A;top:-6px}.fv-fv em{color:#00995A;bottom:auto;top:26px}
.fv-m{margin:18px 0 0;padding-left:18px;font-size:13.5px;line-height:1.7}
.th-k{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:10px}.th-k>div{background:#F7F9FC;border-radius:12px;padding:10px 14px}.th-k span{display:block;font-size:12.5px;color:var(--mut);font-weight:600}.th-k b{display:block;font:800 20px 'Space Grotesk',sans-serif;margin-top:2px}.th-k b .badge{font-size:12.5px}.th-k small{font-size:12px;color:var(--mut)}
.th-read{font-size:14px;margin:4px 0 6px;font-weight:600}
.sg-g{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:22px}.sg-h{display:flex;justify-content:space-between;gap:10px;align-items:baseline;margin-bottom:8px}.sg-h b{font-size:15.5px}.sg-h span{font-size:12.5px}
.sg-bar{display:flex;height:22px;border-radius:8px;overflow:hidden;margin-bottom:10px}.sg-bar i{display:block;height:100%}
.sg-t td,.sg-t th{padding:6px 8px}.sg-dot{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:8px;vertical-align:-1px}
.sg-tl{font-size:12.5px;color:var(--mut);font-weight:600;margin:12px 0 6px}.sg-trend{display:flex;gap:8px;align-items:flex-end;height:120px}.sg-col{flex:1;display:flex;flex-direction:column;align-items:center;height:100%;justify-content:flex-end}
.sg-stack{width:70%;display:flex;flex-direction:column-reverse;border-radius:4px;overflow:hidden}.sg-stack i{display:block;width:100%}.sg-col small{font-size:10.5px;color:var(--mut);margin-top:4px;white-space:nowrap}
.sg-warn{background:#FFF7E0;border:1px solid #F2D27A;border-radius:10px;padding:8px 12px;font-size:13px;margin:0 0 10px}
.etf-w{display:inline-block;width:70px;height:8px;background:#EEF2F8;border-radius:4px;margin-right:8px;vertical-align:middle;overflow:hidden}.etf-w i{display:block;height:100%;background:#2F6BFF}
#scr-saved{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 14px}.scr-chip{display:inline-flex;align-items:center;border:1.5px solid #2F6BFF;border-radius:999px;overflow:hidden}.scr-chip a{padding:4px 10px;font:600 13px Inter,sans-serif;color:#2F6BFF;text-decoration:none}.scr-chip button{border:0;background:#EEF4FF;color:#2F6BFF;cursor:pointer;padding:4px 8px;font-size:14px}
#navlinks a.nav-plans{color:#7C3AED;font-weight:700}
.pl-note{background:#F5F3FF;border:1px solid #DDD6FE;border-radius:12px;padding:12px 16px;font-size:14px;margin-bottom:18px}
.pl-g{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:22px;align-items:stretch}
.pl{position:relative;background:#fff;border:1.5px solid var(--line);border-top:5px solid var(--c);border-radius:18px;padding:22px 22px 18px;display:flex;flex-direction:column}
.pl.hot{border-color:var(--c);box-shadow:0 14px 34px rgba(124,58,237,.18)}.pl-hot{position:absolute;top:-13px;right:18px;background:var(--c);color:#fff;font:800 11.5px Inter,sans-serif;letter-spacing:.04em;padding:4px 10px;border-radius:999px}
.pl h3{margin:0;font:800 24px 'Space Grotesk',sans-serif;color:var(--c)}.pl-tag{margin:4px 0 12px;font-size:13.5px;color:var(--mut)}
.pl-p b{font:800 40px 'Space Grotesk',sans-serif}.pl-p span{font-size:14px;color:var(--mut);margin-left:6px}.pl-yr{font-size:12.5px;color:var(--mut);margin:2px 0 14px}
.pl-cta{width:100%;padding:12px;font-size:15px}.pl.hot .pl-cta{background:linear-gradient(120deg,#4C1D95,#7C3AED)}
.pl ul{margin:16px 0 0;padding:0;list-style:none;font-size:13.5px;line-height:1.5}.pl li{padding:6px 0 6px 24px;position:relative;border-top:1px dashed var(--line)}.pl li::before{content:'✓';position:absolute;left:2px;color:var(--c);font-weight:800}
.pl-t td,.pl-t th{padding:9px 10px}.pl-y{color:#00995A;font-size:16px}.pl-n{color:#CBD5E1}
.pl-r{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.pl-rc{border:1px solid var(--line);border-radius:14px;padding:14px 16px}.pl-rh{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px}.pl-rh b{font-size:15.5px}.pl-rc p{margin:0;font-size:13.5px;line-height:1.55;color:#334155}
.pl-chat{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.pl-q{background:#F5F3FF;border-radius:14px 14px 14px 4px;padding:10px 14px;font-size:14px;color:#4C1D95;font-weight:600}
.pl-faq{margin-top:18px}.pl-faq details{border-bottom:1px solid var(--line);padding:12px 4px}.pl-faq summary{cursor:pointer;font-weight:700}.pl-faq p{margin:8px 0 0;color:#334155;font-size:14px}
@media (max-width:860px){.pl-g,.pl-r{grid-template-columns:1fr}.pl-chat{grid-template-columns:1fr}.fv-top{grid-template-columns:1fr}.sg-g{grid-template-columns:1fr}.hm-leg{margin-left:0}}
.pl:last-child .pl-cta{background:linear-gradient(120deg,#A07800,#E0B400);color:#fff}
